package main

import (
        "fmt"
        "os"

        "gopkg.in/yaml.v3"
)

// flowr is a workflow orchestrator. This is only the starter skeleton: it
// compiles and runs, but no subcommands are implemented yet. Implementing the
// CLI described in the round instructions (parsing the YAML workflow, running
// the step DAG, the run report, the append-only event log, etc.) is the task.
//
// The flowr module already depends on gopkg.in/yaml.v3; the helper below keeps
// that dependency referenced so the module graph and the pre-warmed offline
// build cache stay consistent for the agent's own build.
func parseWorkflow(data []byte) (map[string]any, error) {
        var doc map[string]any
        if err := yaml.Unmarshal(data, &doc); err != nil {
                return nil, err
        }
        return doc, nil
}

func main() {
        _ = parseWorkflow
        if len(os.Args) > 1 {
                fmt.Fprintf(os.Stderr, "flowr: subcommand %q is not implemented yet\n", os.Args[1])
        } else {
                fmt.Fprintln(os.Stderr, "flowr: not implemented yet")
        }
        os.Exit(1)
}
