cat > cmd/flowr/main.go <<'EOF'
package main

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"math/rand"
	"os"
	"os/exec"
	"os/signal"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"time"

	"gopkg.in/yaml.v3"
)

const exitOK = 0
const exitFailed = 1
const exitUnknown = 3
const exitValidation = 4
const exitMissing = 5

var nowFunc = time.Now

type Workflow struct {
	Env   map[string]string
	Hooks map[string]string
	Steps []Step
}

type Step struct {
	Name      string
	Cmd       string
	Pipe      []string
	Env       map[string]string
	Needs     []string
	Matrix    map[string][]string
	Retries   *int
	Retry     *RetryPolicy
	When      string
	Foreach   *ForeachSpec
	Inputs    []string
	Outputs   []string
	OnFailure string
	Resources map[string]int
	TimeoutMs *int
}

type RetryPolicy struct {
	Count     int
	Backoff   string
	InitialMs int
	MaxMs     int
	Jitter    bool
}

type ForeachSpec struct {
	Items any
}

type stepRef struct {
	Name string
	Key  string
}

func parseWorkflowBytes(data []byte) (*Workflow, error) {
	var doc map[string]any
	dec := yaml.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&doc); err != nil {
		return nil, err
	}
	wf := &Workflow{}
	if envAny, ok := doc["env"]; ok {
		env, err := toStringMap("env", envAny)
		if err != nil {
			return nil, err
		}
		wf.Env = env
	}
	if hooksAny, ok := doc["hooks"]; ok {
		hooks, err := parseHooks(hooksAny)
		if err != nil {
			return nil, err
		}
		wf.Hooks = hooks
	}
	if stepsAny, ok := doc["steps"]; ok {
		steps, err := parseSteps(stepsAny)
		if err != nil {
			return nil, err
		}
		wf.Steps = steps
	}
	return wf, nil
}

func parseHooks(v any) (map[string]string, error) {
	m, ok := v.(map[string]any)
	if !ok {
		return nil, fmt.Errorf("hooks must be a mapping")
	}
	allowed := map[string]bool{"on_start": true, "on_success": true, "on_failure": true}
	out := map[string]string{}
	for k, vv := range m {
		if !allowed[k] {
			return nil, fmt.Errorf("unknown hook: %s", k)
		}
		s, err := toNonEmptyString(fmt.Sprintf("hooks.%s", k), vv)
		if err != nil {
			return nil, err
		}
		if strings.ContainsRune(s, 0) {
			return nil, fmt.Errorf("hook %s must not contain NUL bytes", k)
		}
		out[k] = s
	}
	return out, nil
}

func parseSteps(v any) ([]Step, error) {
	arr, ok := v.([]any)
	if !ok {
		return nil, fmt.Errorf("steps must be a sequence")
	}
	var out []Step
	for i, item := range arr {
		s, err := parseStep(item, i)
		if err != nil {
			return nil, err
		}
		out = append(out, s)
	}
	return out, nil
}

func parseStep(v any, idx int) (Step, error) {
	m, ok := v.(map[string]any)
	if !ok {
		return Step{}, fmt.Errorf("step %d must be a mapping", idx)
	}
	allowed := map[string]bool{
		"name": true, "cmd": true, "pipe": true, "env": true, "needs": true,
		"matrix": true, "retries": true, "retry": true, "when": true,
		"foreach": true, "inputs": true, "outputs": true, "on_failure": true,
		"resources": true, "timeout_ms": true,
	}
	for k := range m {
		if !allowed[k] {
			return Step{}, fmt.Errorf("unknown step field: %s", k)
		}
	}
	var s Step
	ns, ok := m["name"]
	if !ok {
		return Step{}, fmt.Errorf("step %d missing name", idx)
	}
	name, err := toNonEmptyString("name", ns)
	if err != nil {
		return Step{}, err
	}
	if strings.ContainsRune(name, 0) {
		return Step{}, fmt.Errorf("step name must not contain NUL bytes")
	}
	s.Name = name
	if v, ok := m["cmd"]; ok {
		s.Cmd, err = toString("cmd", v)
		if err != nil {
			return Step{}, err
		}
	}
	if v, ok := m["pipe"]; ok {
		s.Pipe, err = toStringList("pipe", v)
		if err != nil {
			return Step{}, err
		}
	}
	if v, ok := m["env"]; ok {
		s.Env, err = toStringMap("env", v)
		if err != nil {
			return Step{}, err
		}
	}
	if v, ok := m["needs"]; ok {
		s.Needs, err = toStringList("needs", v)
		if err != nil {
			return Step{}, err
		}
	}
	if v, ok := m["matrix"]; ok {
		s.Matrix, err = parseMatrix(v)
		if err != nil {
			return Step{}, err
		}
	}
	if v, ok := m["retries"]; ok {
		r, err := toInt("retries", v)
		if err != nil {
			return Step{}, err
		}
		if r < 0 {
			return Step{}, fmt.Errorf("retries must be >= 0")
		}
		s.Retries = &r
	}
	if v, ok := m["retry"]; ok {
		rp, err := parseRetry(v)
		if err != nil {
			return Step{}, err
		}
		s.Retry = &rp
	}
	if v, ok := m["when"]; ok {
		s.When, err = toString("when", v)
		if err != nil {
			return Step{}, err
		}
		if strings.ContainsRune(s.When, 0) {
			return Step{}, fmt.Errorf("when expression must not contain NUL bytes")
		}
	}
	if v, ok := m["foreach"]; ok {
		fs, err := parseForeach(v)
		if err != nil {
			return Step{}, err
		}
		s.Foreach = &fs
	}
	if v, ok := m["inputs"]; ok {
		s.Inputs, err = toStringList("inputs", v)
		if err != nil {
			return Step{}, err
		}
	}
	if v, ok := m["outputs"]; ok {
		s.Outputs, err = toStringList("outputs", v)
		if err != nil {
			return Step{}, err
		}
	}
	if v, ok := m["on_failure"]; ok {
		s.OnFailure, err = toString("on_failure", v)
		if err != nil {
			return Step{}, err
		}
		if s.OnFailure != "" && s.OnFailure != "halt" && s.OnFailure != "continue" {
			return Step{}, fmt.Errorf("on_failure must be halt or continue")
		}
	}
	if v, ok := m["resources"]; ok {
		s.Resources, err = toIntMap("resources", v)
		if err != nil {
			return Step{}, err
		}
	}
	if v, ok := m["timeout_ms"]; ok {
		t, err := toInt("timeout_ms", v)
		if err != nil {
			return Step{}, err
		}
		if t < 0 {
			return Step{}, fmt.Errorf("timeout_ms must be >= 0")
		}
		s.TimeoutMs = &t
	}
	if s.OnFailure == "" {
		s.OnFailure = "halt"
	}
	if s.Cmd == "" && len(s.Pipe) == 0 {
		return Step{}, fmt.Errorf("step %s must declare cmd or pipe", s.Name)
	}
	if s.Retries != nil && s.Retry != nil {
		return Step{}, fmt.Errorf("retry and retries are mutually exclusive")
	}
	if s.Matrix != nil && s.Foreach != nil {
		return Step{}, fmt.Errorf("matrix and foreach are mutually exclusive")
	}
	return s, nil
}

func parseRetry(v any) (RetryPolicy, error) {
	m, ok := v.(map[string]any)
	if !ok {
		return RetryPolicy{}, fmt.Errorf("retry must be a mapping")
	}
	allowed := map[string]bool{"count": true, "backoff": true, "initial_ms": true, "max_ms": true, "jitter": true}
	for k := range m {
		if !allowed[k] {
			return RetryPolicy{}, fmt.Errorf("unknown retry field: %s", k)
		}
	}
	rp := RetryPolicy{Backoff: "fixed", InitialMs: 100, MaxMs: 0, Jitter: false}
	if v, ok := m["count"]; !ok {
		return RetryPolicy{}, fmt.Errorf("retry.count is required")
	} else {
		c, err := toInt("retry.count", v)
		if err != nil {
			return RetryPolicy{}, err
		}
		if c < 0 {
			return RetryPolicy{}, fmt.Errorf("retry.count must be >= 0")
		}
		rp.Count = c
	}
	if v, ok := m["backoff"]; ok {
		b, err := toString("retry.backoff", v)
		if err != nil {
			return RetryPolicy{}, err
		}
		if b != "fixed" && b != "linear" && b != "exponential" {
			return RetryPolicy{}, fmt.Errorf("retry.backoff must be fixed, linear, or exponential")
		}
		rp.Backoff = b
	}
	if v, ok := m["initial_ms"]; ok {
		i, err := toInt("retry.initial_ms", v)
		if err != nil {
			return RetryPolicy{}, err
		}
		if i < 0 {
			return RetryPolicy{}, fmt.Errorf("retry.initial_ms must be >= 0")
		}
		rp.InitialMs = i
	}
	if v, ok := m["max_ms"]; ok {
		i, err := toInt("retry.max_ms", v)
		if err != nil {
			return RetryPolicy{}, err
		}
		if i < 0 {
			return RetryPolicy{}, fmt.Errorf("retry.max_ms must be >= 0")
		}
		rp.MaxMs = i
	}
	if v, ok := m["jitter"]; ok {
		b, err := toBool("retry.jitter", v)
		if err != nil {
			return RetryPolicy{}, err
		}
		rp.Jitter = b
	}
	return rp, nil
}

func parseMatrix(v any) (map[string][]string, error) {
	m, ok := v.(map[string]any)
	if !ok {
		return nil, fmt.Errorf("matrix must be a mapping")
	}
	out := map[string][]string{}
	for k, vv := range m {
		vals, err := toStringList(fmt.Sprintf("matrix.%s", k), vv)
		if err != nil {
			return nil, err
		}
		if len(vals) == 0 {
			return nil, fmt.Errorf("matrix axis %s must have at least one value", k)
		}
		out[k] = vals
	}
	return out, nil
}

func parseForeach(v any) (ForeachSpec, error) {
	m, ok := v.(map[string]any)
	if !ok {
		return ForeachSpec{}, fmt.Errorf("foreach must be a mapping")
	}
	for k := range m {
		if k != "items" {
			return ForeachSpec{}, fmt.Errorf("unknown foreach field: %s", k)
		}
	}
	if _, ok := m["items"]; !ok {
		return ForeachSpec{}, fmt.Errorf("foreach.items is required")
	}
	return ForeachSpec{Items: m["items"]}, nil
}

func toString(field string, v any) (string, error) {
	switch x := v.(type) {
	case string:
		return x, nil
	case int:
		return strconv.Itoa(x), nil
	case int64:
		return strconv.FormatInt(x, 10), nil
	case bool:
		if x {
			return "true", nil
		}
		return "false", nil
	case float64:
		return strconv.FormatFloat(x, 'f', -1, 64), nil
	default:
		return "", fmt.Errorf("%s must be a string", field)
	}
}

func toNonEmptyString(field string, v any) (string, error) {
	s, err := toString(field, v)
	if err != nil {
		return "", err
	}
	if s == "" {
		return "", fmt.Errorf("%s must be non-empty", field)
	}
	return s, nil
}

func toInt(field string, v any) (int, error) {
	switch x := v.(type) {
	case int:
		return x, nil
		case int64:
		return int(x), nil
	case string:
		i, err := strconv.Atoi(strings.TrimSpace(x))
		if err != nil {
			return 0, fmt.Errorf("%s must be an integer", field)
		}
		return i, nil
	default:
		return 0, fmt.Errorf("%s must be an integer", field)
	}
}

func toBool(field string, v any) (bool, error) {
	switch x := v.(type) {
	case bool:
		return x, nil
	case string:
		b, err := strconv.ParseBool(strings.TrimSpace(x))
		if err != nil {
			return false, fmt.Errorf("%s must be a boolean", field)
		}
		return b, nil
	default:
		return false, fmt.Errorf("%s must be a boolean", field)
	}
}

func toStringList(field string, v any) ([]string, error) {
	arr, ok := v.([]any)
	if !ok {
		return nil, fmt.Errorf("%s must be a sequence", field)
	}
	var out []string
	for i, item := range arr {
		s, err := toString(fmt.Sprintf("%s[%d]", field, i), item)
		if err != nil {
			return nil, err
		}
		out = append(out, s)
	}
	return out, nil
}

func toStringMap(field string, v any) (map[string]string, error) {
	m, ok := v.(map[string]any)
	if !ok {
		return nil, fmt.Errorf("%s must be a mapping", field)
	}
	out := map[string]string{}
	for k, vv := range m {
		s, err := toString(fmt.Sprintf("%s.%s", field, k), vv)
		if err != nil {
			return nil, err
		}
		out[k] = s
	}
	return out, nil
}

func toIntMap(field string, v any) (map[string]int, error) {
	m, ok := v.(map[string]any)
	if !ok {
		return nil, fmt.Errorf("%s must be a mapping", field)
	}
	out := map[string]int{}
	for k, vv := range m {
		i, err := toInt(fmt.Sprintf("%s.%s", field, k), vv)
		if err != nil {
			return nil, err
		}
		if i < 0 {
			return nil, fmt.Errorf("%s.%s must be >= 0", field, k)
		}
		out[k] = i
	}
	return out, nil
}

