func parseRetry(v any) (RetryPolicy, error) {
    m, ok := v.(map[string]any)
    if !ok {
        return RetryPolicy{}, fmt.Errorf("retry must be a mapping")
    }
    allowed := map[string]bool{"count": true, "backoff": true, "initial_ms": true, "max_ms": true, "jitter": true}
    for k := range m {
        if !allowed[k] {
