                return err
            }
            if err := checkForeachOutputRef(wf, s, ref); err != nil {
                return err
            }
        }
    case []any:
        for i, item := range x {
            str, err := toString(fmt.Sprintf("foreach.items[%d]", i), item)
            if err != nil {
                return err
            }
            if str == "" {
                return fmt.Errorf("foreach.items[%d] must be non-empty", i)
            }
            if strings.ContainsRune(str, 0) {
                return fmt.Errorf("foreach.items[%d] must not contain NUL bytes", i)
            }
        }
    default:
        return fmt.Errorf("foreach.items must be a string or sequence")
    }
    return nil
}

func checkForeachOutputRef(wf *Workflow, s *Step, ref stepRef) error {
    if _, ok := findStep(wf, ref.Name); !ok {
        return fmt.Errorf("unknown step reference: %s", ref.Name)
    }
    prod := findStepByName(wf, ref.Name)
    if prod == nil {
        return fmt.Errorf("unknown step reference: %s", ref.Name)
    }
    if prod.Matrix != nil || prod.Foreach != nil {
        return fmt.Errorf("foreach items step reference must be a non-matrix non-foreach step")
    }
    found := false
    for _, n := range s.Needs {
        if n == ref.Name {
            found = true
            break
        }
    }
    if !found {
        return fmt.Errorf("step output reference requires needs: %s", ref.Name)
    }
    return nil
}

func validateStepOutputRefs(wf *Workflow, s Step) error {
    refs := []string{}
    refs = append(refs, extractStepRefs(s.Cmd)...)
    for _, p := range s.Pipe {
        refs = append(refs, extractStepRefs(p)...)
    }
    for _, v := range s.Env {
        refs = append(refs, extractStepRefs(v)...)
    }
    refs = append(refs, extractStepRefs(s.When)...)
    for _, r := range refs {
        ref, err := parseStepOutputRef(r)
        if err != nil {
            continue
        }
        if err := checkStepRef(wf, &s, ref); err != nil {
            return err
        }
    }
    return nil
}

func checkStepRef(wf *Workflow, s *Step, ref stepRef) error {
    if _, ok := findStep(wf, ref.Name); !ok {
        return fmt.Errorf("unknown step reference: %s", ref.Name)
    }
    if !outputKeyRe.MatchString(ref.Key) {
        return fmt.Errorf("invalid step output key: %s", ref.Key)
    }
    prod := findStepByName(wf, ref.Name)
    if prod == nil {
        return fmt.Errorf("unknown step reference: %s", ref.Name)
    }
    if prod.Foreach != nil {
        return fmt.Errorf("step output reference to foreach step is invalid")
    }
    if prod.Matrix != nil && s.Matrix != nil {
        if !sameAxes(prod.Matrix, s.Matrix) {
            return fmt.Errorf("step output reference requires same matrix axes")
        }
    } else if prod.Matrix != nil || s.Matrix != nil {
        return fmt.Errorf("step output reference requires same matrix axes")
    }
    if !transitivelyNeeds(s, ref.Name, wf) {
        return fmt.Errorf("step output reference requires needs: %s", ref.Name)
    }
    return nil
}

func transitivelyNeeds(s *Step, target string, wf *Workflow) bool {
    visited := map[string]bool{}
    var rec func(step *Step) bool
    rec = func(step *Step) bool {
        for _, n := range step.Needs {
            if n == target {
                return true
            }
            if visited[n] {
                continue
            }
            visited[n] = true
            if ns, ok := findStep(wf, n); ok && rec(ns) {
                return true
            }
        }
        return false
    }
    return rec(s)
}

func sameAxes(a, b map[string][]string) bool {
    if len(a) != len(b) {
        return false
    }
    for k, av := range a {
        bv, ok := b[k]
        if !ok || len(av) != len(bv) {
            return false
        }
        for i := range av {
            if av[i] != bv[i] {
                return false
            }
        }
    }
    return true
}

func detectCycles(wf *Workflow) error {
    visited := map[string]int{}
    var visit func(*Step) error
    visit = func(s *Step) error {
        if visited[s.Name] == 1 {
            return fmt.Errorf("cycle detected")
        }
        if visited[s.Name] == 2 {
            return nil
        }
        visited[s.Name] = 1
        for _, n := range s.Needs {
            ns, ok := findStep(wf, n)
            if !ok {
                continue
            }
            if err := visit(ns); err != nil {
                return err
            }
        }
        visited[s.Name] = 2
        return nil
    }
    for i := range wf.Steps {
        if err := visit(&wf.Steps[i]); err != nil {
            return err
        }
    }
    return nil
}

func findStep(wf *Workflow, name string) (*Step, bool) {
    for i := range wf.Steps {
        if wf.Steps[i].Name == name {
            return &wf.Steps[i], true
        }
    }
    return nil, false
}

func findStepByName(wf *Workflow, name string) *Step {
    s, ok := findStep(wf, name)
    if !ok {
        return nil
    }
    return s
}

func isStepOutputRef(s string) bool {
    return strings.HasPrefix(s, "step.") && strings.Contains(s, ".output.")
}

func parseStepOutputRef(s string) (stepRef, error) {
    s = strings.TrimSpace(s)
    if !strings.HasPrefix(s, "${step.") || !strings.HasSuffix(s, "}") {
        return stepRef{}, fmt.Errorf("invalid step output reference")
    }
    inner := s[2 : len(s)-1]
    parts := strings.SplitN(inner, ".", 4)
    if len(parts) != 4 || parts[0] != "step" || parts[2] != "output" {
        return stepRef{}, fmt.Errorf("invalid step output reference")
    }
    return stepRef{Name: parts[1], Key: parts[3]}, nil
}

func extractStepRefs(s string) []string {
    var refs []string
    for _, m := range varRefRe.FindAllString(s, -1) {
        inner := m[2 : len(m)-1]
        if strings.HasPrefix(inner, "step.") && strings.Contains(inner, ".output.") {
            refs = append(refs, m)
        }
    }
    return refs
}

func validateWhenSyntax(expr string) error {
    e := strings.TrimSpace(expr)
    if strings.ContainsRune(e, 0) {
        return fmt.Errorf("invalid when expression: %s", expr)
    }
    if e == "true" || e == "false" {
        return nil
    }
    for _, op := range []string{"==", "!=", "<=", ">=", "<", ">"} {
        if idx := strings.Index(e, op); idx > 0 {
            lhs := strings.TrimSpace(e[:idx])
            rhs := strings.TrimSpace(e[idx+len(op):])
            if lhs == "" || rhs == "" {
                break
            }
            if op == "==" || op == "!=" {
                if validWhenOperand(lhs) && validWhenOperand(rhs) {
                    return nil
                }
            } else {
                if isIntLiteral(lhs) && isIntLiteral(rhs) {
                    return nil
                }
            }
            break
        }
    }
    return fmt.Errorf("invalid when expression: %s", expr)
}

func validWhenOperand(s string) bool {
    if s == "true" || s == "false" {
        return false
    }
    if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
        inner := s[1 : len(s)-1]
        if inner == "" {
            return false
        }
        return !strings.ContainsRune(inner, '\'')
    }
    return identRe.MatchString(s)
}

func isIntLiteral(s string) bool {
    if s == "" {
        return false
    }
    if s[0] == '-' || s[0] == '+' {
        s = s[1:]
    }
    if s == "" {
        return false
    }
    for _, r := range s {
        if r < '0' || r > '9' {
            return false
        }
    }
    return true
}
