package main

import (
    "encoding/json"
    "fmt"
    "regexp"
    "sort"
    "strconv"
    "strings"
)

var varRefRe = regexp.MustCompile(`\$\{([^}]*)\}`)

func interpolateFirstPass(s string, envs []map[string]string, builtins map[string]string) (string, error) {
    var missing []string
    result := varRefRe.ReplaceAllStringFunc(s, func(m string) string {
        inner := m[2 : len(m)-1]
        if strings.HasPrefix(inner, "step.") && strings.Contains(inner, ".output.") {
            return m
        }
        for _, e := range envs {
            if e != nil {
                if v, ok := e[inner]; ok {
                    return v
                }
            }
        }
        if builtins != nil {
            if v, ok := builtins[inner]; ok {
                return v
            }
        }
        missing = append(missing, inner)
        return m
    })
    if len(missing) > 0 {
        return "", fmt.Errorf("undefined variable: %s", missing[0])
    }
    return result, nil
}

func interpolateStepEnv(s string, stepEnv, wfEnv, parentEnv map[string]string, builtins map[string]string) (string, error) {
    return interpolateFirstPass(s, []map[string]string{stepEnv, wfEnv, parentEnv}, builtins)
}

func resolveStepOutputs(s string, outputs map[string]map[string]any) (string, error) {
    var missing []string
    result := varRefRe.ReplaceAllStringFunc(s, func(m string) string {
        inner := m[2 : len(m)-1]
        if !strings.HasPrefix(inner, "step.") || !strings.Contains(inner, ".output.") {
            return m
        }
        ref, err := parseStepOutputRef(m)
        if err != nil {
            missing = append(missing, err.Error())
            return m
        }
        prod, ok := outputs[ref.Name]
        if !ok {
            missing = append(missing, fmt.Sprintf("missing_step_output:%s.%s", ref.Name, ref.Key))
            return m
        }
        val, ok := prod[ref.Key]
        if !ok {
            missing = append(missing, fmt.Sprintf("missing_step_output:%s.%s", ref.Name, ref.Key))
            return m
        }
        str, err := outputValueToString(val)
        if err != nil {
            missing = append(missing, err.Error())
            return m
        }
        return str
    })
    if len(missing) > 0 {
        return "", fmt.Errorf("%s", missing[0])
    }
    return result, nil
}

func outputValueToString(v any) (string, error) {
    switch x := v.(type) {
    case string:
        return x, nil
    case bool:
        if x {
            return "true", nil
        }
        return "false", nil
    case float64:
        return strconv.FormatFloat(x, 'f', -1, 64), nil
    case int:
        return strconv.Itoa(x), nil
    case int64:
        return strconv.FormatInt(x, 10), nil
    case json.Number:
        return x.String(), nil
    case []any:
        parts := make([]string, 0, len(x))
        for _, e := range x {
            switch et := e.(type) {
            case string:
                parts = append(parts, et)
            default:
                b, err := json.Marshal(et)
                if err != nil {
                    return "", err
                }
                parts = append(parts, string(b))
            }
        }
        return strings.Join(parts, ","), nil
    default:
        b, err := json.Marshal(v)
        if err != nil {
            return "", err
        }
        return string(b), nil
    }
}

