package main

import (
    "encoding/json"
    "fmt"
    "os"
    "path/filepath"
    "sort"
    "strconv"
    "strings"
)

func expandMatrix(step *Step) []*ExpandedStep {
    if step.Matrix == nil {
        es := &ExpandedStep{Base: step, Name: step.Name}
        es.Env = buildCellEnv(step, nil, nil)
        return []*ExpandedStep{es}
    }
    axes := make([]string, 0, len(step.Matrix))
    for k := range step.Matrix {
        axes = append(axes, k)
    }
    sort.Strings(axes)
    var combos [][]map[string]string
    var rec func(int, []map[string]string)
    rec = func(i int, cur []map[string]string) {
        if i == len(axes) {
            combo := make([]map[string]string, len(cur))
            copy(combo, cur)
            combos = append(combos, combo)
            return
        }
        for _, v := range step.Matrix[axes[i]] {
            rec(i+1, append(cur, map[string]string{axes[i]: v}))
        }
    }
    rec(0, nil)
    var out []*ExpandedStep
    for _, combo := range combos {
        axesMap := map[string]string{}
        parts := []string{}
        for _, m := range combo {
            for k, v := range m {
                axesMap[k] = v
                parts = append(parts, k+"="+v)
            }
        }
        name := step.Name + "[" + strings.Join(parts, ",") + "]"
        es := &ExpandedStep{Base: step, Name: name, MatrixAxes: axesMap}
        es.Env = buildCellEnv(step, axesMap, nil)
        out = append(out, es)
    }
    return out
}

func buildCellEnv(step *Step, matrixAxes map[string]string, foreachItem *string) map[string]string {
    out := map[string]string{}
    for k, v := range step.Env {
        out[k] = v
    }
    if matrixAxes != nil {
        for k, v := range matrixAxes {
            out["FLOWR_MATRIX_"+k] = v
        }
    }
    if foreachItem != nil {
        out["FLOWR_FOREACH_ITEM"] = *foreachItem
    }
    return out
}

func expandForeach(rt *Runtime, step *Step) ([]*ExpandedStep, error) {
    items, err := resolveForeachItems(rt, step)
    if err != nil {
        return nil, err
    }
    if len(items) == 0 {
        return nil, nil
    }
    var out []*ExpandedStep
    for i, item := range items {
        idx := i
        it := item
        name := step.Name + "[idx=" + strconv.Itoa(i) + "]"
        es := &ExpandedStep{Base: step, Name: name, ForeachIdx: &idx, ForeachItem: &it}
        es.Env = buildCellEnv(step, nil, &it)
        out = append(out, es)
    }
    return out, nil
}

func resolveForeachItems(rt *Runtime, step *Step) ([]string, error) {
    switch x := step.Foreach.Items.(type) {
    case string:
        if isStepOutputRef(x) {
            ref, err := parseStepOutputRef(x)
            if err != nil {
                return nil, err
            }
            prod, ok := rt.outputs[ref.Name]
            if !ok {
                return nil, fmt.Errorf("missing_step_output")
            }
            val, ok := prod[ref.Key]
            if !ok {
                return nil, fmt.Errorf("missing_step_output")
            }
            arr, ok := val.([]any)
            if !ok {
                return nil, fmt.Errorf("step output %s.%s must be an array of strings", ref.Name, ref.Key)
            }
            out := make([]string, 0, len(arr))
            for _, e := range arr {
                s, ok := e.(string)
                if !ok {
                    return nil, fmt.Errorf("step output %s.%s must be an array of strings", ref.Name, ref.Key)
                }
                out = append(out, s)
            }
            return out, nil
        }
        interpolated, err := interpolateFirstPass(x, []map[string]string{step.Env, rt.wf.Env, rt.parentEnv}, nil)
        if err != nil {
            return nil, err
        }
        if interpolated == "" {
            return nil, nil
        }
        parts := strings.Split(interpolated, ",")
        out := make([]string, 0, len(parts))
        for _, p := range parts {
            p = strings.TrimSpace(p)
            if p == "" {
                return nil, fmt.Errorf("empty foreach item")
            }
            out = append(out, p)
        }
        return out, nil
    case []any:
        out := make([]string, 0, len(x))
        for i, item := range x {
            s, err := toString(fmt.Sprintf("foreach.items[%d]", i), item)
            if err != nil {
                return nil, err
            }
            interpolated, err := interpolateFirstPass(s, []map[string]string{step.Env, rt.wf.Env, rt.parentEnv}, nil)
            if err != nil {
                return nil, err
            }
            if interpolated == "" {
                return nil, fmt.Errorf("empty foreach item")
            }
            out = append(out, interpolated)
        }
        return out, nil
    default:
        return nil, fmt.Errorf("foreach.items must be a string or sequence")
    }
}

func outputJSONPath(rt *Runtime, expandedName string) string {
    return filepath.Join(rt.runDir, "steps", expandedName, "output.json")
}

func loadStepOutput(rt *Runtime, expandedName string) (map[string]any, error) {
    path := outputJSONPath(rt, expandedName)
    data, err := os.ReadFile(path)
    if err != nil {
        return nil, err
    }
    var v any
    dec := json.NewDecoder(strings.NewReader(string(data)))
    dec.UseNumber()
    if err := dec.Decode(&v); err != nil {
        return nil, err
    }
    obj, ok := v.(map[string]any)
    if !ok {
        return nil, fmt.Errorf("bad_output_json")
    }
    for k, vv := range obj {
        if !outputKeyRe.MatchString(k) {
            return nil, fmt.Errorf("bad_output_json")
        }
        if !validOutputValue(vv) {
            return nil, fmt.Errorf("bad_output_json")
        }
    }
    return obj, nil
}

func validOutputValue(v any) bool {
    switch x := v.(type) {
    case string, bool, json.Number:
        return true
    case float64, int, int64:
        return true
    case []any:
        for _, e := range x {
            s, ok := e.(string)
            if !ok || s == "" {
                return false
            }
        }
        return true
    default:
        return false
    }
}

func allNeedsTerminal(rt *Runtime, es *ExpandedStep) bool {
    for _, n := range es.Base.Needs {
        if !needsStepTerminal(rt, n) {
            return false
        }
    }
    return true
}

func needsStepTerminal(rt *Runtime, baseName string) bool {
    cells := rt.expandedCellsForBase(baseName)
    if cells == nil {
        st, ok := rt.statuses[baseName]
        return ok && isTerminal(st)
    }
    for _, c := range cells {
        st, ok := rt.statuses[c]
        if !ok || !isTerminal(st) {
            return false
        }
    }
    return true
}

func isTerminal(status string) bool {
    switch status {
    case "ok", "cached", "failed", "cancelled", "skipped", "conditionally_skipped", "inherited":
        return true
    default:
        return false
    }
}

func isFailureStatus(status string) bool {
    return status == "failed" || status == "cancelled"
}

func expandedCellsForBase(rt *Runtime, baseName string) []string {
    if cells, ok := rt.foreachCells[baseName]; ok {
        return cells
    }
    if cells, ok := rt.matrixCells[baseName]; ok {
        return cells
    }
    return nil
}

func expandBaseIfNeeded(rt *Runtime, step *Step) ([]string, error) {
    if step.Foreach != nil {
        if rt.foreachDone[step.Name] {
            return rt.foreachCells[step.Name], nil
        }
        cells, err := expandForeach(rt, step)
        if err != nil {
            return nil, err
        }
        names := make([]string, 0, len(cells))
        for _, es := range cells {
            rt.expandedSteps[es.Name] = es
            rt.statuses[es.Name] = "pending"
            names = append(names, es.Name)
        }
        if len(names) == 0 {
            rt.statuses[step.Name] = "skipped"
            sr := StepReport{Name: step.Name, Status: "skipped", Reason: "empty_foreach", RetryAttempts: []int{}}
            rt.reports[step.Name] = sr
            emitEvent(rt, map[string]any{"event": "step_skipped", "step": step.Name, "reason": "empty_foreach"})
            rt.foreachCells[step.Name] = nil
            rt.foreachDone[step.Name] = true
            return nil, nil
        }
        rt.foreachCells[step.Name] = names
        rt.foreachDone[step.Name] = true
        emitEvent(rt, map[string]any{"event": "step_foreach_expanded", "step": step.Name, "count": len(names), "cells": names})
        return names, nil
    }
    cells := expandMatrix(step)
    names := make([]string, 0, len(cells))
    for _, es := range cells {
        rt.expandedSteps[es.Name] = es
        if _, ok := rt.statuses[es.Name]; !ok {
            rt.statuses[es.Name] = "pending"
        }
        names = append(names, es.Name)
    }
    if step.Matrix != nil {
        rt.matrixCells[step.Name] = names
    }
    return names, nil
}

func computeClosure(rt *Runtime, names []string, skip bool) map[string]bool {
    out := map[string]bool{}
    var visit func(string)
    visit = func(name string) {
        if out[name] {
            return
        }
        out[name] = true
        for _, s := range rt.wf.Steps {
            for _, n := range s.Needs {
                if n == name {
                    visit(s.Name)
                }
            }
        }
    }
    for _, n := range names {
        visit(n)
    }
    return out
}

func baseNamesFromExpanded(name string) string {
    if i := strings.IndexByte(name, '['); i > 0 {
        return name[:i]
    }
    return name
}
