func runResume(priorID, newID, maxParallel, onlyStep, skipStep, slots string, noCache bool) int {
    priorDir := filepath.Join(".flowr", "runs", priorID)
    snapPath := filepath.Join(priorDir, "workflow.yaml.snapshot")
    reportPath := filepath.Join(priorDir, "report.json")
    if !fileExists(priorDir) {
        fatalErr("cannot resume: %s", priorDir)
        return exitMissing
    }
    if !fileExists(snapPath) || !fileExists(reportPath) {
        fatalErr("cannot resume: %s", missingPath(snapPath, reportPath))
        return exitMissing
    }
    data, err := os.ReadFile(snapPath)
    if err != nil {
        fatalErr("cannot resume: %v", err)
        return exitMissing
    }
    wf, err := parseWorkflowBytes(data)
    if err != nil {
        fatalErr("%v", err)
        return exitValidation
    }
    parentEnv := envMapFromOS()
    if err := validateWorkflow(wf, parentEnv); err != nil {
        fatalErr("%v", err)
        return exitValidation
    }
    var priorReport Report
    if err := readJSONFile(reportPath, &priorReport); err != nil {
        fatalErr("cannot resume: %v", err)
        return exitMissing
    }
    absSnap, _ := filepath.Abs(snapPath)
    if err := validateHookInterpolation(wf, parentEnv, newID, absSnap); err != nil {
        fatalErr("%v", err)
        return exitValidation
    }
    rt := newRuntime(wf, newID, absSnap, maxParallel, onlyStep, skipStep, slots, noCache, priorID)
    if err := initRunDir(rt, data, false); err != nil {
        fatalErr("%v", err)
        return exitFailed
    }
    applyResume(rt, &priorReport)
    return runWorkflow(rt)
}

func missingPath(paths ...string) string {
    for _, p := range paths {
        if !fileExists(p) {
            return p
        }
    }
    return ""
}

func newRuntime(wf *Workflow, runID, wfPath, maxParallel, onlyStep, skipStep, slots string, noCache bool, resume string) *Runtime {
    rt := &Runtime{
        wf:            wf,
        runID:         runID,
        runDir:        filepath.Join(".flowr", "runs", runID),
        workflowFile:  wfPath,
        snapshotPath:  filepath.Join(".flowr", "runs", runID, "workflow.yaml.snapshot"),
        eventsFile:    filepath.Join(".flowr", "runs", runID, "events.ndjson"),
        reportPath:    filepath.Join(".flowr", "runs", runID, "report.json"),
        cacheDir:      filepath.Join(".flowr", "cache"),
        maxParallel:   1,
        slots:         parseSlots(slots),
        noCache:        noCache,
        only:          parseNames(onlyStep),
        skip:          parseNames(skipStep),
        resume:        resume,
        resumedFrom:   resume,
        parentEnv:     envMapFromOS(),
        steps:         map[string]*Step{},
        expandedSteps: map[string]*ExpandedStep{},
        matrixCells:   map[string][]string{},
        foreachCells:  map[string][]string{},
        foreachDone:   map[string]bool{},
        stepDirs:      map[string]string{},
        statuses:      map[string]string{},
        reports:       map[string]StepReport{},
        outputs:       map[string]map[string]any{},
        orderAttempt:  []string{},
        cacheHits:     []string{},
        cacheMisses:   []string{},
        resourceUsed:  map[string]int{},
        running:       map[string]bool{},
        runningCmds:   map[string]*exec.Cmd{},
        hookReport:    map[string]HookReport{
            "on_start":   {Executed: false, ExitCode: nil, DurationMs: 0},
            "on_success": {Executed: false, ExitCode: nil, DurationMs: 0},
            "on_failure": {Executed: false, ExitCode: nil, DurationMs: 0},
        },
    }
    if mp, err := atoiNonNeg("max-parallel", maxParallel); err == nil && mp > 0 {
        rt.maxParallel = mp
    }
    for i := range wf.Steps {
        s := &wf.Steps[i]
        rt.steps[s.Name] = s
    }
    for _, s := range wf.Steps {
        if s.Foreach != nil {
            rt.statuses[s.Name] = "pending"
            continue
        }
        cells := expandMatrix(s)
        for _, es := range cells {
            rt.expandedSteps[es.Name] = es
            rt.statuses[es.Name] = "pending"
            if s.Matrix != nil {
                rt.matrixCells[s.Name] = append(rt.matrixCells[s.Name], es.Name)
            }
        }
    }
    if err := rt.validateOnlySkip(); err != nil {
        fatalErr("%v", err)
        os.Exit(exitUnknown)
    }
    rt.onlyClosure = rt.computeOnlyClosure()
    rt.skipClosure = rt.computeSkipClosure()
    return rt
}

func (rt *Runtime) validateOnlySkip() error {
    all := map[string]bool{}
    for name := range rt.expandedSteps {
        all[name] = true
    }
    for _, s := range rt.wf.Steps {
        all[s.Name] = true
        if s.Foreach != nil {
            for i := 0; i < 100; i++ {
                all[fmt.Sprintf("%s[idx=%d]", s.Name, i)] = true
            }
        }
    }
    for n := range rt.only {
        if !all[n] && !rt.baseExists(n) {
            return fmt.Errorf("unknown step reference: %s", n)
        }
    }
    for n := range rt.skip {
        if !all[n] && !rt.baseExists(n) {
            return fmt.Errorf("unknown step reference: %s", n)
        }
    }
    return nil
}

func (rt *Runtime) baseExists(name string) bool {
    for _, s := range rt.wf.Steps {
        if s.Name == name {
            return true
        }
    }
    return false
}

func parseNames(s string) map[string]bool {
    out := map[string]bool{}
    for _, p := range strings.Split(s, ",") {
        p = strings.TrimSpace(p)
        if p != "" {
            out[p] = true
        }
    }
    return out
}

func parseSlots(s string) map[string]int {
    out := map[string]int{}
    for _, p := range strings.Split(s, ",") {
        p = strings.TrimSpace(p)
        if p == "" {
            continue
        }
        kv := strings.SplitN(p, "=", 2)
        if len(kv) != 2 {
            continue
        }
        n, err := atoiNonNeg(kv[0], kv[1])
        if err != nil {
            continue
        }
        out[strings.TrimSpace(kv[0])] = n
    }
    return out
}

func atoiNonNeg(field, s string) (int, error) {
    i, err := parseInt(strings.TrimSpace(s))
    if err != nil {
        return 0, fmt.Errorf("%s must be an integer", field)
    }
    if i < 0 {
        return 0, fmt.Errorf("%s must be >= 0", field)
    }
    return i, nil
}

func parseInt(s string) (int, error) {
    var n int
    _, err := fmt.Sscanf(s, "%d", &n)
    return n, err
}

func newRunID() string {
    return fmt.Sprintf("run-%d", nowFunc().UnixNano())
}

func initRunDir(rt *Runtime, snapshotData []byte, fresh bool) error {
    if err := ensureDir(rt.runDir); err != nil {
        return err
    }
    if err := ensureDir(filepath.Join(rt.runDir, "steps")); err != nil {
        return err
    }
    if err := ensureDir(filepath.Join(rt.runDir, "hooks")); err != nil {
        return err
    }
    if err := writeBytes(rt.snapshotPath, snapshotData); err != nil {
        return err
    }
    if fresh {
        emitEvent(rt, map[string]any{"event": "run_started", "run_id": rt.runID})
    } else {
        inherited, rerun := rt.resumeLists()
        emitEvent(rt, map[string]any{
            "event":           "run_resumed",
            "run_id":          rt.runID,
            "resumed_from":    rt.resumedFrom,
            "inherited_steps": inherited,
            "rerun_steps":     rerun,
        })
    }
    return nil
}

func (rt *Runtime) resumeLists() ([]string, []string) {
    var inh, rerun []string
    for name := range rt.expandedSteps {
        if rt.statuses[name] == "inherited" {
            inh = append(inh, name)
        } else if rt.statuses[name] != "inherited" && rt.statuses[name] != "" {
            rerun = append(rerun, name)
        }
    }
    for _, s := range rt.wf.Steps {
        if s.Foreach != nil && rt.statuses[s.Name] == "inherited" {
            inh = append(inh, s.Name)
        }
    }
    sort.Strings(inh)
    sort.Strings(rerun)
    return inh, rerun
}

func applyResume(rt *Runtime, prior *Report) {
    for name, sr := range prior.Steps {
        switch sr.Status {
        case "ok", "cached", "conditionally_skipped", "skipped":
            if es, ok := rt.expandedSteps[name]; ok {
                rt.statuses[name] = "inherited"
                nr := sr
                nr.Status = "inherited"
                nr.Attempts = 0
                nr.ExitCode = nil
                nr.DurationMs = 0
                nr.StartedAt = nil
                nr.EndedAt = nil
                nr.RetryAttempts = []int{}
                nr.OriginalStatus = sr.Status
                rt.reports[name] = nr
                copyPriorOutput(rt, name, sr)
                _ = es
            } else if base, ok := rt.steps[name]; ok && base.Foreach != nil {
                rt.statuses[name] = "inherited"
                nr := sr
                nr.Status = "inherited"
                nr.OriginalStatus = sr.Status
                nr.RetryAttempts = []int{}
                rt.reports[name] = nr
            }
        case "failed", "cancelled":
            if _, ok := rt.expandedSteps[name]; ok {
                rt.statuses[name] = "pending"
            } else if base, ok := rt.steps[name]; ok && base.Foreach != nil {
                rt.statuses[name] = "pending"
            }
        }
    }
}

func copyPriorOutput(rt *Runtime, name string, sr StepReport) {
    priorDir := filepath.Join(".flowr", "runs", rt.resumedFrom, "steps", name, "output.json")
    if fileExists(priorDir) {
        dst := outputJSONPath(rt, name)
        if err := copyFile(priorDir, dst); err == nil {
            if obj, err := loadStepOutput(rt, name); err == nil {
                rt.outputs[name] = obj
            }
        }
    }
}

func runWorkflow(rt *Runtime) int {
    sigCh := make(chan os.Signal, 2)
    signal.Notify(sigCh, syscall.SIGTERM, syscall.SIGINT)
    go func() {
        <-sigCh
        rt.cancelRun()
    }()

    if err := runHook(rt, "on_start"); err != nil {
        rt.hookReport["on_start"] = rt.hookReport["on_start"]
        rt.mu.Lock()
        for name := range rt.statuses {
            if rt.statuses[name] == "pending" {
                rt.statuses[name] = "cancelled"
                rt.reports[name] = StepReport{Name: name, Status: "cancelled", ExitCode: nil, DurationMs: 0, RetryAttempts: []int{}}
            }
        }
        rt.mu.Unlock()
        finalizeRun(rt, "failed")
        return exitFailed
    }

    status := scheduler(rt)
    if rt.cancelled {
        status = "failed"
    }
    if status == "ok" {
        runHook(rt, "on_success")
    } else {
        runHook(rt, "on_failure")
    }
    finalizeRun(rt, status)
    if status == "ok" {
        return exitOK
    }
    return exitFailed
}

func scheduler(rt *Runtime) string {
    completions := make(chan completion, 1024)
    var active int
    for {
        rt.mu.Lock()
        if rt.cancelled {
            rt.mu.Unlock()
            break
        }
        rt.expandReadyForeach()
        rt.propagateSkips()
        ready := rt.readySteps()
        sort.Strings(ready)
        started := false
        for _, name := range ready {
            if active >= rt.maxParallel {
                break
            }
            if !rt.canReserve(name) {
                continue
            }
            es := rt.expandedSteps[name]
            if es == nil {
                continue
            }
            if rt.onlyClosure != nil && !rt.inOnlyClosure(name) {
                rt.statuses[name] = "skipped"
                rt.reports[name] = StepReport{Name: name, Status: "skipped", Reason: "only_filter", RetryAttempts: []int{}}
                continue
            }
            if rt.skipClosure != nil && rt.skipClosure[name] {
                rt.statuses[name] = "skipped"
                rt.reports[name] = StepReport{Name: name, Status: "skipped", Reason: "skip_filter", RetryAttempts: []int{}}
                continue
            }
            rt.reserve(name)
            rt.running[name] = true
            active++
            started = true
            go func(es *ExpandedStep) {
                status, err := executeStep(rt, es)
                completions <- completion{name: es.Name, status: status, err: err}
            }(es)
        }
        rt.mu.Unlock()
        if active == 0 && !started {
            break
        }
        if active > 0 {
            comp := <-completions
            active--
            rt.mu.Lock()
            delete(rt.running, comp.name)
            rt.release(comp.name)
            if comp.status == "failed" || comp.status == "cancelled" {
                if rt.expandedSteps[comp.name] != nil && rt.expandedSteps[comp.name].Base.OnFailure == "halt" {
                    rt.halted = true
                }
            }
            rt.mu.Unlock()
        }
    }
    close(completions)
    for c := range completions {
        _ = c
    }
    rt.mu.Lock()
    defer rt.mu.Unlock()
    failed := false
    for _, st := range rt.statuses {
        if st == "failed" || st == "cancelled" {
            failed = true
            break
        }
    }
    if failed {
        return "failed"
    }
    return "ok"
}

func (rt *Runtime) expandReadyForeach() {
    for _, s := range rt.wf.Steps {
        if s.Foreach == nil || rt.foreachDone[s.Name] {
            continue
        }
        if rt.statuses[s.Name] != "pending" {
            continue
        }
        if !allNeedsTerminal(rt, &s) {
            continue
        }
        cells, err := expandBaseIfNeeded(rt, &s)
        if err != nil {
            rt.statuses[s.Name] = "failed"
            rt.reports[s.Name] = StepReport{Name: s.Name, Status: "failed", Error: err.Error(), RetryAttempts: []int{}}
            rt.halted = true
        }
        _ = cells
    }
}

func (rt *Runtime) propagateSkips() {
    for name, es := range rt.expandedSteps {
        if rt.statuses[name] != "pending" {
            continue
        }
        if rt.halted {
            rt.statuses[name] = "skipped"
            rt.reports[name] = StepReport{Name: name, Status: "skipped", Reason: "halted", RetryAttempts: []int{}}
            continue
        }
        for _, n := range es.Base.Needs {
            if rt.dependencyFailed(n) {
                rt.statuses[name] = "skipped"
                rt.reports[name] = StepReport{Name: name, Status: "skipped", Reason: "dependency_failed", RetryAttempts: []int{}}
                break
            }
            if rt.dependencyEmptyForeach(n) {
                rt.statuses[name] = "skipped"
                rt.reports[name] = StepReport{Name: name, Status: "skipped", Reason: "parent_empty_foreach", RetryAttempts: []int{}}
                break
            }
        }
    }
}

func (rt *Runtime) dependencyFailed(baseName string) bool {
    cells := expandedCellsForBase(rt, baseName)
    if cells == nil {
        st, ok := rt.statuses[baseName]
        return ok && (st == "failed" || st == "cancelled")
    }
    for _, c := range cells {
        st, ok := rt.statuses[c]
        if ok && (st == "failed" || st == "cancelled") {
            return true
        }
    }
    return false
}

func (rt *Runtime) dependencyEmptyForeach(baseName string) bool {
    st, ok := rt.statuses[baseName]
    return ok && st == "skipped" && rt.reports[baseName].Reason == "empty_foreach"
}

func (rt *Runtime) readySteps() []string {
    var ready []string
    for name, es := range rt.expandedSteps {
        if rt.statuses[name] != "pending" {
            continue
        }
        if rt.running[name] {
            continue
        }
        if !allNeedsTerminal(rt, es) {
            continue
        }
        if rt.hasFailedNeed(es) {
            continue
        }
        ready = append(ready, name)
    }
    return ready
}

func (rt *Runtime) hasFailedNeed(es *ExpandedStep) bool {
    for _, n := range es.Base.Needs {
        if rt.dependencyFailed(n) || rt.dependencyEmptyForeach(n) {
            return true
        }
    }
    return false
}

func (rt *Runtime) canReserve(name string) bool {
    es := rt.expandedSteps[name]
    if es == nil {
        return false
    }
    for k, v := range es.Base.Resources {
        avail, ok := rt.slots[k]
        if !ok {
            return false
        }
        if rt.resourceUsed[k]+v > avail {
            return false
        }
    }
    return true
}

func (rt *Runtime) reserve(name string) {
    es := rt.expandedSteps[name]
    if es == nil {
        return
    }
    for k, v := range es.Base.Resources {
        rt.resourceUsed[k] += v
        if rt.resourceUsed[k] > rt.resourceUsed["max_"+k] {
            rt.resourceUsed["max_"+k] = rt.resourceUsed[k]
        }
    }
}

func (rt *Runtime) release(name string) {
    es := rt.expandedSteps[name]
    if es == nil {
        return
    }
    for k, v := range es.Base.Resources {
        rt.resourceUsed[k] -= v
        if rt.resourceUsed[k] < 0 {
            rt.resourceUsed[k] = 0
        }
    }
}

func (rt *Runtime) inOnlyClosure(name string) bool {
    if rt.onlyClosure == nil {
        return true
    }
    if rt.onlyClosure[name] {
        return true
    }
    base := baseNamesFromExpanded(name)
    return rt.onlyClosure[base]
}

func (rt *Runtime) computeOnlyClosure() map[string]bool {
    if len(rt.only) == 0 {
        return nil
    }
    out := map[string]bool{}
    var visit func(string)
    visit = func(name string) {
        if out[name] {
            return
        }
        out[name] = true
        base := baseNamesFromExpanded(name)
        if s, ok := rt.steps[base]; ok {
            for _, n := range s.Needs {
                if cells, ok := rt.matrixCells[n]; ok {
                    for _, c := range cells {
                        visit(c)
                    }
                } else if cells, ok := rt.foreachCells[n]; ok {
                    for _, c := range cells {
                        visit(c)
                    }
                } else {
                    visit(n)
                }
            }
        }
    }
    for n := range rt.only {
        visit(n)
    }
    return out
}

func (rt *Runtime) computeSkipClosure() map[string]bool {
    if len(rt.skip) == 0 {
        return nil
    }
    out := map[string]bool{}
    var visit func(string)
    visit = func(name string) {
        if out[name] {
            return
        }
        out[name] = true
        for _, s := range rt.wf.Steps {
            for _, n := range s.Needs {
                if n == name || n == baseNamesFromExpanded(name) {
                    if s.Foreach != nil {
                        for _, c := range rt.foreachCells[s.Name] {
                            visit(c)
                        }
                    } else if s.Matrix != nil {
                        for _, c := range rt.matrixCells[s.Name] {
                            visit(c)
                        }
                    } else {
                        visit(s.Name)
                    }
                }
            }
        }
    }
    for n := range rt.skip {
        visit(n)
    }
    return out
}

func (rt *Runtime) cancelRun() {
    rt.mu.Lock()
    rt.cancelled = true
    cmds := make([]*exec.Cmd, 0, len(rt.runningCmds))
    for _, c := range rt.runningCmds {
        cmds = append(cmds, c)
    }
    rt.mu.Unlock()
    for _, c := range cmds {
        if c != nil && c.Process != nil {
            c.Process.Signal(syscall.SIGTERM)
        }
    }
    go func() {
        time.Sleep(sigtermGraceMs * time.Millisecond)
        rt.mu.Lock()
        for _, c := range rt.runningCmds {
            if c != nil && c.Process != nil {
                c.Process.Kill()
            }
        }
        rt.mu.Unlock()
    }()
}

func finalizeRun(rt *Runtime, status string) {
    rt.mu.Lock()
    end := timestampNow()
    steps := map[string]StepReport{}
    for name, es := range rt.expandedSteps {
        sr, ok := rt.reports[name]
        if !ok {
            sr = StepReport{Name: name, Status: rt.statuses[name], RetryAttempts: []int{}}
            if sr.Status == "" {
                sr.Status = "skipped"
            }
        }
        sr.Name = name
        sr.RetryAttempts = ensureRetryAttempts(sr.RetryAttempts)
        steps[name] = sr
        rt.reports[name] = sr
        writeStepMeta(rt, name, sr)
        _ = es
    }
    for _, s := range rt.wf.Steps {
        if s.Foreach != nil {
            if sr, ok := rt.reports[s.Name]; ok && sr.Status != "" {
                sr.RetryAttempts = ensureRetryAttempts(sr.RetryAttempts)
                steps[s.Name] = sr
                writeStepMeta(rt, s.Name, sr)
            }
        }
    }
    started := ""
    if sr, ok := rt.reports[""]; ok {
        started = sr.StartedAt
    }
    rep := Report{
        RunID:            rt.runID,
        WorkflowFile:     rt.workflowFile,
        StartedAt:        started,
        EndedAt:          end,
        TotalDurationMs:  0,
        MaxParallel:      rt.maxParallel,
        Status:           status,
        Steps:            steps,
        OrderAttempted:   rt.orderAttempted,
        CacheHits:        rt.cacheHits,
        CacheMisses:      rt.cacheMisses,
        ResourceStats:    rt.resourceStats(),
        Hooks:            rt.hookReport,
        StepOutputs:       rt.outputs,
        ResumedFrom:      rt.resumedFromPtr(),
    }
    rt.mu.Unlock()
    writeJSONFile(rt.reportPath, rep)
}

func (rt *Runtime) resumedFromPtr() *string {
    if rt.resumedFrom == "" {
        return nil
    }
    return &rt.resumedFrom
}

func (rt *Runtime) resourceStats() map[string]int {
    out := map[string]int{}
    for k, v := range rt.resourceUsed {
        if strings.HasPrefix(k, "max_") {
            out[strings.TrimPrefix(k, "max_")] = v
        }
    }
    return out
}

func ensureRetryAttempts(a []int) []int {
    if a == nil {
        return []int{}
    }
    return a
}

func writeStepMeta(rt *Runtime, name string, sr StepReport) {
    dir := filepath.Join(rt.runDir, "steps", name)
    ensureDir(dir)
    writeJSONFile(filepath.Join(dir, "meta.json"), sr)
}
